/**
 ******************************************************************************
 * @file    fx_job.c
 * TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Jack's storage subsystem (best-ui), with an AI coding assistant;
 *          Brendon (integrator) made effect-file jobs resumable, exactly or by a rebuild with a pre-roll and the carry (30 Oct 2026, with an AI coding assistant).
 * @brief   The effect-file job engine. fx_job.h has the whole job lifecycle
 *          as a numbered list and the message sketch between
 *          JackStorageTask and FxRenderTask; this file follows it.
 *
 * Pure logic: no RTOS, no HAL, no FatFs (tests: Tests/test_fx_job.c). The
 * card is reached only through Interfaces/storage_port.h, FxRenderTask only
 * through ops->send, and the time comes in as now_ms.
 *
 * One effect-file job. Each fxj_step() call does one phase step and returns,
 * because one SD write can stall for 250 ms and a command must never wait
 * for more than one step:
 *
 *   from            event                           to
 *   J_MKDIR_ROOT    "FX" exists or was made         J_MKDIR_EFFECT
 *   J_MKDIR_EFFECT  "FX/<EFFECT>" exists or made    J_CLEAN
 *   J_CLEAN         old .TMP and .WAV unlinked      J_OPEN_SRC
 *                   (a resumed job KEEPS its .TMP
 *                   if its size is what it wrote)
 *   J_OPEN_SRC      the recording checked, open     J_SPACE
 *                   (a resumed job: at the sample
 *                   where it stopped, if the
 *                   recording is the same; a
 *                   rebuild: at its pre-roll)
 *   J_SPACE         enough free space for the rest  J_CREATE
 *   J_CREATE        .TMP made, header written       J_RUN
 *                   (a resumed job: its .TMP
 *                   opened again, at its end)
 *   J_RUN           every chunk written             J_CLOSE
 *   J_CLOSE         real header, files closed       J_RENAME
 *   J_RENAME        .TMP renamed to .WAV            (done)
 *   any phase       an error                        (failed: a class of fxj_fail_t)
 *   any phase       fxj_park()                      (parked: from J_RUN on, its resume
 *                                                   point goes to the park table)
 *   any phase       fxj_abort()                     (no job; .TMP left for J_CLEAN)
 *   any phase       the user waits for the job,     (gave up: give_up(); the
 *                   and FxRenderTask has not        original plays; .TMP left
 *                   answered (or sends were         for J_CLEAN)
 *                   refused) for FXJ_STALL_MS
 *   any phase       a background job while          (stays in its phase: it
 *                   background work is not allowed  waits)
 *
 * Card writes per step, at worst (each one can keep the card busy 250 ms):
 * J_MKDIR_* about 68 the first time per card (FatFs zeroes the new folder's
 * 32 KB cluster), else 0; J_CLEAN 8; J_CREATE 5; one J_RUN write of 16 KB
 * plus 4; J_CLOSE 4; J_RENAME 2.
 *
 * FatFs lock slots: FatFs here has two (_FS_LOCK 2), and a running job holds
 * both, the recording (from J_OPEN_SRC) and the .TMP (from J_CREATE). So
 * every play, record, delete and remount path in jack_audio_sd.c parks the
 * job (or, when its files must go, aborts it) before it opens anything; a
 * parked job holds no slot. A close that fails keeps its slot (FatFs frees
 * it only after a good close), so a failed close asks for a remount
 * (remount_wanted), which empties the lock table.
 *
 * Map of this file, top to bottom (start reading at "The step"):
 *   Small helpers               min, percent steps, log line, failure classes
 *   Source facts                fxj_fingerprint: what a recording looks like
 *   The validity check          fxj_check: is an old effect file still good?
 *   The park table              rows of parked pairs: take, put, hold, drop
 *   Starting and ending a job   start_job, end_job_done / _failed, give_up
 *   Carrying on                 the checks of a resumed job; exact, or the
 *                               rebuild (pre-roll + carry)
 *   The phases                  one function per phase, run_phase, next_phase
 *   J_RUN                       run_read, run_send, run_write, step_run
 *   Parking                     fxj_park / fxj_park_for: stop for now, keep
 *                               the progress
 *   The step                    fxj_step: the job's next step, or one
 *                               background check that may start a job
 *                               (a parked job that can carry on exactly
 *                               goes first)
 *   Replies                     fxj_on_reply: FxRenderTask's answer
 *   The rest of the interface   init, mount, want / unwant / abort, status
 ******************************************************************************/
#include "fx_job.h"
#include <stdio.h>
#include <string.h>

#define FXJ_PERCENT_ALL       100U
#define FXJ_BYTES_PER_SAMPLE  2U        /* mono 16-bit */
#define FXJ_BYTES_PER_KB      1024U
#define FXJ_MS_PER_S          1000U
#define FXJ_MS_PER_TENTH      100U
#define FXJ_TENTHS_PER_S      10U
#define FXJ_RATE_32K_HZ       32000U    /* a recording: the 2:3 upsampler first */
#define FXJ_RATE_48K_HZ       48000U    /* a 48 kHz PC file: no upsampler */
#define FXJ_OUT_PER_BLOCK     96U       /* 64 samples at 32 kHz become 96 at 48 kHz (2:3) */
#define FXJ_FIRST_JOB_ID      1U
#define FXJ_OUT_PER_MS        48U       /* effect files are 48 kHz: 48 samples per ms (for the log) */

/* ======================================================================= */
/* Small helpers                                                            */
/* ======================================================================= */

static uint32_t min_u32(uint32_t a, uint32_t b)
{
    return (a < b) ? a : b;
}

static uint8_t round_down(uint8_t percent, uint8_t step)
{
    return (uint8_t)(percent - (percent % step));
}

static uint8_t effect_bit(uint8_t effect)
{
    if (effect < FXS_EFFECT_AUTOTUNE || effect > FXS_EFFECT_COUNT)
    {
        return 0U;
    }
    return (uint8_t)(1U << (effect - 1U));
}

static const char *effect_name(uint8_t effect)
{
    const char *folder = fx_folder(effect);
    return (folder != NULL) ? folder : "?";
}

/* Hand one finished line to the log hook, if there is one. The host tests
 * read these lines; the firmware passes NULL (its serial console was
 * removed on 1 Nov 2026). */
static void log_line(const fxj_t *j, const char *line)
{
    if (j->ops != NULL && j->ops->log != NULL)
    {
        j->ops->log(j->ops->ctx, line);
    }
}

/* The class of a failed card call. Only a disk-level error is the card's
 * fault. A refusal by the file system, and a "not found" where something
 * must exist, are REFUSED. */
static fxj_fail_t fail_class(storage_result_t r)
{
    switch (r)
    {
        case STORAGE_OK:         return FXJ_FAIL_NONE;
        case STORAGE_SLOW:       return FXJ_FAIL_NONE;     /* complete, only late: a slow write is no error */
        case STORAGE_FULL:       return FXJ_FAIL_FULL;
        case STORAGE_READ_FAIL:  return FXJ_FAIL_CARD_READ;
        case STORAGE_WRITE_FAIL: return FXJ_FAIL_CARD_WRITE;
        case STORAGE_NO_SLOT:    return FXJ_FAIL_NO_SLOT;
        default:                 return FXJ_FAIL_REFUSED;
    }
}

static const char *fail_text(fxj_fail_t fail)
{
    switch (fail)
    {
        case FXJ_FAIL_FULL:        return "card full";
        case FXJ_FAIL_CARD_READ:   return "card read failed";
        case FXJ_FAIL_CARD_WRITE:  return "card write failed";
        case FXJ_FAIL_REFUSED:     return "refused by the file system";
        case FXJ_FAIL_NO_SLOT:     return "no free lock slot";
        case FXJ_FAIL_SOURCE:      return "the recording is not a WAV it can use";
        case FXJ_FAIL_NO_ENGINE:   return "no effect engine in this build";
        case FXJ_FAIL_BAD_REQUEST: return "FxRenderTask refused a chunk";
        default:                   return "?";
    }
}

/* How many 48 kHz samples the effect file of n source samples has: the same
 * rule as Tom's FxRender_OutputSamples (96 per full block of 64 at 32 kHz,
 * 3/2 of a partial block; as many as the source at 48 kHz). */
static uint32_t output_samples(uint32_t n, bool src_48k)
{
    if (src_48k)
    {
        return n;
    }
    return FXJ_OUT_PER_BLOCK * (n / FXP_BLOCK_SAMPLES) + (3U * (n % FXP_BLOCK_SAMPLES)) / 2U;
}

static bool source_is_48k(const fx_src_t *src)
{
    return src->rate == FXJ_RATE_48K_HZ;
}

/* A failed close may keep its lock slot: ask for the remount. */
static void close_read_file(fxj_t *j)
{
    if (Storage_Close() != STORAGE_OK)
    {
        j->remount_wanted = true;
    }
}

/* The size of a .TMP with n effect samples after its header. */
static uint32_t tmp_bytes(uint32_t n)
{
    return FXS_HEADER_BYTES + n * FXJ_BYTES_PER_SAMPLE;
}

/* ======================================================================= */
/* Source facts                                                             */
/* ======================================================================= */

/* Mono 16-bit, 32 or 48 kHz, at least one sample and at most
 * FXJ_MAX_SOURCE_S seconds of audio: then it can have effect files. */
static bool is_renderable(const fx_src_t *src)
{
    if (!src->playable)
    {
        return false;
    }
    if (src->rate != FXJ_RATE_32K_HZ && src->rate != FXJ_RATE_48K_HZ)
    {
        return false;
    }
    const uint32_t max_bytes = FXJ_MAX_SOURCE_S * src->rate * FXJ_BYTES_PER_SAMPLE;
    return (src->data_size >= FXJ_BYTES_PER_SAMPLE) && (src->data_size <= max_bytes);
}

static void fill_source_facts(fx_src_t *src, const storage_stat_t *st, const wav_header_t *hdr, uint32_t hash)
{
    memset(src, 0, sizeof(*src));
    src->size        = st->size;
    src->hash        = hash;
    src->rate        = hdr->sample_rate;
    src->data_offset = hdr->data_offset;
    src->data_size   = hdr->data_size;
    src->fdate       = st->fdate;
    src->ftime       = st->ftime;
    src->channels    = hdr->num_channels;
    src->bits        = hdr->bits_per_sample;
    src->playable    = (src->channels == 1U) && (src->bits == 16U);
    src->renderable  = is_renderable(src);
}

/* The facts of the open read/play file: its first 512 bytes (the WAV
 * header, and the hash's head) and its last 512 bytes (the hash's tail). */
static storage_result_t read_open_file_facts(fxj_t *j, const storage_stat_t *st, fx_src_t *src)
{
    const uint32_t head_len = min_u32(FXS_HASH_PART_BYTES, st->size);
    size_t got = 0U;
    if (Storage_ReadChunk(j->scratch, head_len, &got) != STORAGE_OK)
    {
        return STORAGE_READ_FAIL;
    }
    wav_header_t hdr;
    if (got != head_len || wav_parse_header(j->scratch, got, st->size, &hdr) != STORAGE_OK)
    {
        return STORAGE_CORRUPT;
    }
    uint32_t hash = fx_hash_add(fx_hash_begin(), j->scratch, got);
    if (st->size > FXS_HASH_PART_BYTES)
    {
        const uint32_t tail_len = min_u32(FXS_HASH_PART_BYTES, st->size - FXS_HASH_PART_BYTES);
        if (Storage_Seek(st->size - tail_len) != STORAGE_OK)
        {
            return STORAGE_READ_FAIL;
        }
        if (Storage_ReadChunk(j->scratch, tail_len, &got) != STORAGE_OK)
        {
            return STORAGE_READ_FAIL;
        }
        if (got != tail_len)
        {
            return STORAGE_CORRUPT;
        }
        hash = fx_hash_add(hash, j->scratch, got);
    }
    fill_source_facts(src, st, &hdr, hash);
    return STORAGE_OK;
}

/* Open recording name as the read/play file and read its facts. On
 * STORAGE_OK the file stays open (J_OPEN_SRC keeps it, fxj_fingerprint
 * closes it); on anything else it is closed again. */
static storage_result_t open_source(fxj_t *j, const char *name, fx_src_t *src)
{
    storage_stat_t st;
    storage_result_t r = Storage_Stat(name, &st);
    if (r == STORAGE_READ_FAIL)
    {
        return STORAGE_READ_FAIL;
    }
    if (r != STORAGE_OK || st.is_dir)
    {
        return STORAGE_NOT_FOUND;
    }
    r = Storage_OpenRead(name);
    if (r == STORAGE_NO_SLOT)
    {
        j->remount_wanted = true;
        return STORAGE_NO_SLOT;
    }
    if (r == STORAGE_READ_FAIL)
    {
        return STORAGE_READ_FAIL;
    }
    if (r != STORAGE_OK)
    {
        return STORAGE_NOT_FOUND;
    }
    r = read_open_file_facts(j, &st, src);
    if (r != STORAGE_OK)
    {
        close_read_file(j);
    }
    return r;
}

storage_result_t fxj_fingerprint(fxj_t *j, const char *name, fx_src_t *src)
{
    if (j == NULL || name == NULL || src == NULL)
    {
        return STORAGE_INVALID_ARG;
    }
    const storage_result_t r = open_source(j, name, src);
    if (r == STORAGE_OK)
    {
        close_read_file(j);
    }
    return r;
}

/* ======================================================================= */
/* The validity check (rules 1-4 below)                                     */
/* ======================================================================= */

/* Rule 1: a 48 kHz mono 16-bit WAV. */
static bool is_effect_format(const wav_header_t *hdr)
{
    return (hdr->sample_rate == FXS_RATE_HZ) && (hdr->num_channels == 1U) && (hdr->bits_per_sample == 16U);
}

/* Rule 3: complete. The size the header DECLARES must be exactly what
 * follows it, and even. (wav_parse_header clamps a declared size of 0, or
 * one past the end, to the end of the file, so its data_size alone would
 * pass a file cut short.) */
static bool is_complete(const wav_header_t *hdr, uint32_t file_size)
{
    if (hdr->data_size_clamped || hdr->data_offset > file_size)
    {
        return false;
    }
    return (hdr->declared_data_size == file_size - hdr->data_offset) &&
           ((hdr->declared_data_size % FXJ_BYTES_PER_SAMPLE) == 0U);
}

/* Rules 1-3 on the effect file that is open as the read/play file. */
static fxj_valid_t check_open_effect_file(fxj_t *j, uint8_t effect, const fx_src_t *src,
                                          uint32_t size, wav_header_t *hdr)
{
    const uint32_t head_len = min_u32(FXJ_SCRATCH_BYTES, size);
    size_t got = 0U;
    if (Storage_ReadChunk(j->scratch, head_len, &got) != STORAGE_OK)
    {
        return FXJ_IO_ERROR;
    }
    if (wav_parse_header(j->scratch, got, size, hdr) != STORAGE_OK || !is_effect_format(hdr))
    {
        return FXJ_STALE;
    }
    /* Rule 2: the tag says it was made from this recording, as it is now,
     * by this version of the effect. */
    fx_tag_t found;
    fx_tag_t wanted;
    if (fx_parse_tag(j->scratch, got, &found) != STORAGE_OK)
    {
        return FXJ_STALE;
    }
    fx_tag_from_src(&wanted, FXJ_RENDER_VERSION, effect, src);
    if (!fx_tag_matches(&found, &wanted) || !is_complete(hdr, size))
    {
        return FXJ_STALE;
    }
    return FXJ_VALID;
}

fxj_valid_t fxj_check(fxj_t *j, const char *name, uint8_t effect, const fx_src_t *src,
                      bool keep_open, wav_header_t *hdr)
{
    char wav[FXS_PATH_LEN];
    char tmp[FXS_PATH_LEN];
    if (j == NULL || src == NULL ||
        !fx_file_path(effect, name, false, wav, sizeof(wav)) || !fx_file_path(effect, name, true, tmp, sizeof(tmp)))
    {
        return FXJ_STALE;
    }
    storage_stat_t st;
    storage_result_t r = Storage_Stat(wav, &st);
    if (r == STORAGE_READ_FAIL)
    {
        return FXJ_IO_ERROR;
    }
    if (r != STORAGE_OK || st.is_dir)
    {
        return FXJ_STALE;                                  /* not made yet */
    }
    /* Rule 4: a .TMP beside a complete .WAV can only come from a power loss
     * inside the rename, which leaves both names on one cluster chain: the
     * pair is made again (J_CLEAN then frees that chain once). */
    storage_stat_t tmp_st;
    r = Storage_Stat(tmp, &tmp_st);
    if (r == STORAGE_READ_FAIL)
    {
        return FXJ_IO_ERROR;
    }
    if (r == STORAGE_OK)
    {
        return FXJ_STALE;
    }
    r = Storage_OpenRead(wav);
    if (r == STORAGE_READ_FAIL)
    {
        return FXJ_IO_ERROR;
    }
    if (r != STORAGE_OK)
    {
        if (r == STORAGE_NO_SLOT)
        {
            j->remount_wanted = true;
        }
        return FXJ_STALE;
    }
    wav_header_t found;
    fxj_valid_t v = check_open_effect_file(j, effect, src, st.size, &found);
    if (v == FXJ_VALID && keep_open)
    {
        if (Storage_Seek(found.data_offset) == STORAGE_OK)
        {
            if (hdr != NULL)
            {
                *hdr = found;
            }
            return FXJ_VALID;                               /* it stays open at its first sample */
        }
        v = FXJ_IO_ERROR;
    }
    close_read_file(j);
    return v;
}

/* ======================================================================= */
/* The park table (TEAM CODE, written by Brendon, 30 Oct 2026)              */
/* ======================================================================= */
/* One row per parked (recording, effect) pair, at most FXJ_PARK_ROWS. A
 * pair that runs again takes its row out first (fxj_want, check_pair), so a
 * pair is never both in the slot and in the table.
 *
 * One more place holds a row for a moment: j->held. A PLAY parks the slot
 * job BEFORE it knows whether the effect file must be made (fxj_park_for),
 * so the row of the pair it may wait for is set aside first. Then a full
 * table can never drop that row to make room for the park, and the
 * fxj_want that follows takes it from there. If no want comes (the file
 * was made after all, or the play failed), the next fxj_step puts it back. */

/* Is row the row of pair (name, effect)? */
static bool row_is(const fxj_parked_t *row, const char *name, uint8_t effect)
{
    return row->used && row->effect == effect && strncmp(row->name, name, FXS_NAME_LEN) == 0;
}

/* The row of pair (name, effect) in the table, or NULL. */
static fxj_parked_t *find_row(fxj_t *j, const char *name, uint8_t effect)
{
    for (uint32_t i = 0U; i < FXJ_PARK_ROWS; i++)
    {
        if (row_is(&j->parked[i], name, effect))
        {
            return &j->parked[i];
        }
    }
    return NULL;
}

/* Take the pair's row out (it is about to run): the held row if it is this
 * pair's, else its row in the table. True, with *out filled, when it had one. */
static bool take_row(fxj_t *j, const char *name, uint8_t effect, fxj_resume_t *out)
{
    fxj_parked_t *row = row_is(&j->held, name, effect) ? &j->held : find_row(j, name, effect);
    if (row == NULL)
    {
        return false;
    }
    *out = row->resume;
    memset(row, 0, sizeof(*row));
    return true;
}

/* A full table drops its oldest row (the smallest parked_no). Its .TMP is
 * unlinked at once (an unlink needs no lock slot), so no partial file that
 * nobody will carry on stays on the card; if the unlink fails, that pair's
 * next J_CLEAN removes it. */
static fxj_parked_t *drop_oldest_row(fxj_t *j)
{
    fxj_parked_t *oldest = &j->parked[0];
    for (uint32_t i = 1U; i < FXJ_PARK_ROWS; i++)
    {
        if (j->parked[i].parked_no < oldest->parked_no)
        {
            oldest = &j->parked[i];
        }
    }
    char tmp[FXS_PATH_LEN];
    if (fx_file_path(oldest->effect, oldest->name, true, tmp, sizeof(tmp)))
    {
        (void)Storage_Unlink(tmp);
    }
    char line[FXJ_LOG_LEN];
    (void)snprintf(line, sizeof(line), "FX %s %s: its parked progress is dropped (park table full)",
                   effect_name(oldest->effect), oldest->name);
    log_line(j, line);
    memset(oldest, 0, sizeof(*oldest));
    return oldest;
}

/* The row a park writes: the pair's own row if it has one, else an empty
 * row, else the oldest row (dropped first). */
static fxj_parked_t *row_for_park(fxj_t *j, const char *name, uint8_t effect)
{
    fxj_parked_t *row = find_row(j, name, effect);
    if (row != NULL)
    {
        return row;
    }
    for (uint32_t i = 0U; i < FXJ_PARK_ROWS; i++)
    {
        if (!j->parked[i].used)
        {
            return &j->parked[i];
        }
    }
    return drop_oldest_row(j);
}

/* The slot job's resume point goes into the table. */
static void put_row(fxj_t *j)
{
    const fxj_job_t *job = &j->job;
    fxj_parked_t *row = row_for_park(j, job->name, job->effect);
    memset(row, 0, sizeof(*row));
    row->used = true;
    memcpy(row->name, job->name, FXS_NAME_LEN);
    row->effect = job->effect;
    j->parks++;
    row->parked_no = j->parks;
    row->resume = job->resume;
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): the held row goes back into
 * the table (no fxj_want came for it), as a park would put it: its own
 * row, an empty row, or the oldest row's place. It counts as parked now:
 * the user has just asked for that pair. */
static void put_back_held(fxj_t *j)
{
    if (!j->held.used)
    {
        return;
    }
    fxj_parked_t back = j->held;
    memset(&j->held, 0, sizeof(j->held));
    j->parks++;
    back.parked_no = j->parks;
    *row_for_park(j, back.name, back.effect) = back;
}

/* Set the row of pair (name, effect) aside in j->held (fxj_park_for), if it
 * has one. Only one row is held at a time: another pair's goes back first. */
static void hold_row(fxj_t *j, const char *name, uint8_t effect)
{
    if (row_is(&j->held, name, effect))
    {
        return;                                            /* held already (an effect switch, then PLAY) */
    }
    put_back_held(j);
    fxj_parked_t *row = find_row(j, name, effect);
    if (row != NULL)
    {
        j->held = *row;
        memset(row, 0, sizeof(*row));
    }
}

/* Every row of recording name goes (it is deleted, or written over), the
 * held row too. Their .TMP files are not unlinked here: DELETE removes them
 * itself, and J_CLEAN removes one before its pair is made again. */
static void drop_rows_of(fxj_t *j, const char *name)
{
    for (uint32_t i = 0U; i < FXJ_PARK_ROWS; i++)
    {
        fxj_parked_t *row = &j->parked[i];
        if (row->used && strncmp(row->name, name, FXS_NAME_LEN) == 0)
        {
            memset(row, 0, sizeof(*row));
        }
    }
    if (j->held.used && strncmp(j->held.name, name, FXS_NAME_LEN) == 0)
    {
        memset(&j->held, 0, sizeof(j->held));
    }
}

/* ======================================================================= */
/* Starting and ending a job                                                */
/* ======================================================================= */

/* Is this job number taken? 0 is never used (FXJ_NO_JOB); a reply may still
 * be due for req_job; FxRenderTask's effect state is dsp_job's; and a parked
 * job may carry on under its own number. */
static bool id_in_use(const fxj_t *j, uint16_t id)
{
    if (id == FXJ_NO_JOB || id == j->dsp_job || (j->req_out && id == j->req_job))
    {
        return true;
    }
    for (uint32_t i = 0U; i < FXJ_PARK_ROWS; i++)
    {
        if (j->parked[i].used && j->parked[i].resume.id == id)
        {
            return true;
        }
    }
    return false;
}

/* A new job number, never one in use (above): a late reply can never be
 * taken for the new job's, and a job never claims effect state that is not
 * its own. At most 9 numbers are in use, so the loop is short. (No row is
 * held when a job starts: fxj_want and fxj_step put a held row back first.) */
static uint16_t new_job_id(fxj_t *j)
{
    uint16_t id = j->next_id;
    j->next_id++;
    while (id_in_use(j, id))
    {
        id = j->next_id;
        j->next_id++;
    }
    return id;
}

/* Start the job of a pair, at once. resume: the pair's park row, taken out
 * of the table by the caller (NULL = none: the job starts from 0). */
static void start_job(fxj_t *j, const char *name, uint8_t effect, bool wanted, uint32_t now_ms,
                      const fxj_resume_t *resume)
{
    fxj_job_t *job = &j->job;
    memset(job, 0, sizeof(*job));
    job->active = true;
    job->phase = J_MKDIR_ROOT;
    strncpy(job->name, name, FXS_NAME_LEN - 1U);
    job->effect = effect;
    job->wanted = wanted;
    job->id = new_job_id(j);
    job->start_ms = now_ms;
    if (resume != NULL)
    {
        job->resume = *resume;                             /* it carries on where it was parked */
    }
    j->send_refused = false;
    j->park_end = FXJ_NOTHING;                             /* a new job: an older park's end is no news now */
    j->busy_latch = true;                                  /* fx_busy: from the start of a job */
    const bool paths_ok = fx_file_path(effect, name, true, job->tmp_path, sizeof(job->tmp_path)) &&
                          fx_file_path(effect, name, false, job->wav_path, sizeof(job->wav_path));
    if (!paths_ok)
    {
        job->fail_pending = FXJ_FAIL_REFUSED;              /* a name fx_store refuses: the next step ends it */
    }
}

/* Close the job's .TMP if it holds it. A failed close asks for the remount. */
static void close_effect_file(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    if (job->dst_open)
    {
        job->dst_open = false;
        if (Storage_FxClose() != STORAGE_OK)
        {
            j->remount_wanted = true;
        }
    }
}

/* Close whatever the job holds. A failed close asks for the remount. */
static void close_job_files(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    close_effect_file(j);
    if (job->src_open)
    {
        job->src_open = false;
        close_read_file(j);
    }
}

/* The job is over (made, failed, aborted or given up). It is no longer
 * active, so no step, reply or status looks at it, and a stall of refused
 * sends ends with it. Its other fields stay until the next start_job():
 * the callers below still read job->wanted after this call, and after
 * FXJ_WANT_DONE fxj_want_src() hands Jack job->src, the recording's facts,
 * which he needs to play the file just made. */
static void forget_job(fxj_t *j)
{
    j->job.active = false;
    j->send_refused = false;
}

static fxj_step_t end_job_done(fxj_t *j, uint32_t now_ms)
{
    fxj_job_t *job = &j->job;
    const uint32_t made_ms = now_ms - job->start_ms;
    const uint32_t audio_tenths = (job->src.data_size * FXJ_TENTHS_PER_S) /
                                  (job->src.rate * FXJ_BYTES_PER_SAMPLE);
    char line[FXJ_LOG_LEN];
    (void)snprintf(line, sizeof(line), "FX %s %s made in %lu.%lu s (%lu.%lu s audio)",
                   effect_name(job->effect), job->name,
                   (unsigned long)(made_ms / FXJ_MS_PER_S), (unsigned long)((made_ms % FXJ_MS_PER_S) / FXJ_MS_PER_TENTH),
                   (unsigned long)(audio_tenths / FXJ_TENTHS_PER_S), (unsigned long)(audio_tenths % FXJ_TENTHS_PER_S));
    log_line(j, line);
    fxq_mark(&j->queue, job->name, job->effect);
    j->files_made++;
    forget_job(j);
    j->progress++;
    return job->wanted ? FXJ_WANT_DONE : FXJ_BUSY;
}

/* Background work stops until the next mount or delete: a failing or full
 * card is not hammered. */
static void halt_background(fxj_t *j, const char *why)
{
    if (j->bg_halted)
    {
        return;
    }
    j->bg_halted = true;
    char line[FXJ_LOG_LEN];
    (void)snprintf(line, sizeof(line), "effect files paused until the next card or delete: %s", why);
    log_line(j, line);
}

/* What a failure means for the rest of the engine, and for the queue:
 * - a full card or a disk error halts the background;
 * - no lock slot asks for a remount, and the pair runs once more after it
 *   (a second time in a row it is marked like any failure);
 * - a recording that is not usable has all six pairs marked;
 * - any other failure marks only that pair (made again after a touch). */
static void note_failure(fxj_t *j, fxj_fail_t fail)
{
    const fxj_job_t *job = &j->job;
    if (fail == FXJ_FAIL_FULL || fail == FXJ_FAIL_CARD_READ || fail == FXJ_FAIL_CARD_WRITE)
    {
        halt_background(j, fail_text(fail));
    }
    if (fail == FXJ_FAIL_NO_SLOT)
    {
        j->remount_wanted = true;
        if (fxq_no_slot(&j->queue, job->name, job->effect))
        {
            return;                                        /* left queued: it runs again after the remount */
        }
    }
    if (fail == FXJ_FAIL_SOURCE)
    {
        fxq_mark_all(&j->queue, job->name);
        return;
    }
    fxq_mark(&j->queue, job->name, job->effect);
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): a failure that says nothing
 * about the kept .TMP (no free lock slot, or the card could not be read)
 * lets a job that was carrying on keep its park row: it carries on after
 * the remount, or once the card reads again. Any other failure loses it. */
static bool failure_keeps_row(fxj_fail_t fail)
{
    return (fail == FXJ_FAIL_NO_SLOT) || (fail == FXJ_FAIL_CARD_READ);
}

static fxj_step_t end_job_failed(fxj_t *j, fxj_fail_t fail)
{
    fxj_job_t *job = &j->job;
    close_job_files(j);
    j->last_fail = fail;
    char line[FXJ_LOG_LEN];
    (void)snprintf(line, sizeof(line), "FX %s %s not made: %s", effect_name(job->effect), job->name, fail_text(fail));
    log_line(j, line);
    if (job->resume.valid && failure_keeps_row(fail))
    {
        put_row(j);           /* TEAM CODE (Brendon, 30 Oct 2026): it carries on from here next time */
    }
    note_failure(j, fail);
    forget_job(j);
    j->progress++;
    return job->wanted ? FXJ_WANT_FAILED : FXJ_BUSY;
}

/* FxRenderTask has not answered, or the job's sends were refused, for
 * FXJ_STALL_MS: the user stops waiting and the original plays. A request
 * that is out stays recorded, so no new job starts until its late reply
 * comes. A stall of refused sends has nothing out: it ends with the job
 * (forget_job clears it), so the next job may start at once. */
static fxj_step_t give_up(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    char line[FXJ_LOG_LEN];
    (void)snprintf(line, sizeof(line), "FX %s %s: no answer from FxRenderTask for %lu s - the original plays",
                   effect_name(job->effect), job->name, (unsigned long)(FXJ_STALL_MS / FXJ_MS_PER_S));
    log_line(j, line);
    close_job_files(j);
    forget_job(j);
    j->progress++;
    return FXJ_WANT_GAVE_UP;
}

/* ======================================================================= */
/* Carrying on (TEAM CODE, written by Brendon, 30 Oct 2026)                 */
/* ======================================================================= */
/* A job that took a park row (job->resume.valid) walks the usual phases;
 * J_CLEAN, J_OPEN_SRC and J_CREATE use the checks below to carry on instead
 * of starting from 0. A check that finds the .TMP or the recording changed
 * makes the file from the start again, logged, never as an error. (A disk
 * error is a card-read failure as anywhere else; the job keeps its row.)
 * Otherwise it carries on exactly, or (FxRenderTask's state is not its own
 * any more) is rebuilt: resume_not_exact() below. */

/* The resumed job starts again from 0 after all (logged, so a percentage
 * that drops back to 0 is explained). */
static void forget_resume(fxj_t *j, const char *why)
{
    fxj_job_t *job = &j->job;
    char line[FXJ_LOG_LEN];
    (void)snprintf(line, sizeof(line), "FX %s %s made again from 0%% (parked at %u%%): %s",
                   effect_name(job->effect), job->name, (unsigned)job->resume.pct, why);
    log_line(j, line);
    job->resume.valid = false;
}

/* As forget_resume, and its .TMP goes now (J_CREATE makes a new one). */
static fxj_fail_t start_again(fxj_t *j, const char *why)
{
    forget_resume(j, why);
    const storage_result_t r = Storage_Unlink(j->job.tmp_path);
    return (r == STORAGE_OK || r == STORAGE_NOT_FOUND) ? FXJ_FAIL_NONE : fail_class(r);
}

/* J_CLEAN: is the kept .TMP exactly as the park left it, header plus out_at
 * samples? A close that failed, a power loss or a PC leave another size (or
 * no file): then the file is made from the start (logged; phase_clean
 * unlinks the .TMP). A disk error on the Stat says nothing about the file:
 * the job fails as a card read and keeps its row (failure_keeps_row).
 * Stat opens nothing: no lock slot. */
static fxj_fail_t check_kept_tmp(fxj_t *j)
{
    storage_stat_t st;
    const storage_result_t r = Storage_Stat(j->job.tmp_path, &st);
    if (r == STORAGE_READ_FAIL)
    {
        return FXJ_FAIL_CARD_READ;
    }
    if (r != STORAGE_OK || st.is_dir || st.size != tmp_bytes(j->job.resume.out_at))
    {
        forget_resume(j, "its .TMP changed");
    }
    return FXJ_FAIL_NONE;
}

/* The recording is as it was when the job was parked: the facts the tag in
 * the .TMP's header was made from. */
static bool same_recording(const fx_src_t *a, const fx_src_t *b)
{
    return (a->size == b->size) && (a->hash == b->hash) && (a->rate == b->rate) &&
           (a->data_offset == b->data_offset) && (a->data_size == b->data_size) &&
           (a->fdate == b->fdate) && (a->ftime == b->ftime);
}

/* J_OPEN_SRC: the same recording, and a resume point the pipe can make: on
 * a chunk edge (or at the end) and with exactly the effect samples those
 * source samples give. */
static bool resume_matches(const fxj_t *j, uint32_t total)
{
    const fxj_job_t *job = &j->job;
    const fxj_resume_t *r = &job->resume;
    if (!same_recording(&r->src, &job->src) || r->src_at > total)
    {
        return false;
    }
    if (r->src_at < total && (r->src_at % FXP_CHUNK_IN) != 0U)
    {
        return false;
    }
    return r->out_at == output_samples(r->src_at, source_is_48k(&job->src));
}

/* Does FxRenderTask still hold the effect state of job number id, exactly
 * where it was parked? Only if the last chunk it was sent was that job's (no
 * other job ran a chunk since) and its reply came back (dsp_ok). Then the
 * job carries on and its file comes out byte for byte as if made in one go. */
static bool dsp_still_holds(const fxj_t *j, uint16_t id)
{
    return j->dsp_ok && (j->dsp_job == id);
}

/* Why FxRenderTask no longer holds job number id's state, for the log: it
 * still names the job, so the park gave up a chunk that was out (its wait
 * for the reply ran out: FxRenderTask is a chunk ahead), or came in the
 * middle of a rebuild's pre-roll (FxRenderTask is behind); or another job
 * has sent a chunk since. */
static const char *why_not_exact(const fxj_t *j, uint16_t id)
{
    return (j->dsp_job == id) ? "its own state is not where it stopped" : "another job ran since";
}

/* An EXACT resume: FxRenderTask still holds the job's effect state (or
 * nothing is left to render, so no state is needed). The pipe carries on
 * where the job was parked, with no FIRST chunk, under the job's old number
 * (FxRenderTask's state is that number's). */
static void carry_on_exactly(fxj_t *j, uint32_t total)
{
    fxj_job_t *job = &j->job;
    const fxj_resume_t *r = &job->resume;
    if (r->src_at < total)
    {
        job->id = r->id;
    }
    fxp_continue(&job->pipe, total, r->src_at, r->out_at);
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): where a rebuild that
 * carries on at source sample `at` starts (S), in source samples: the last
 * multiple of FXJ_PREROLL_GRID_OUT output samples that is at least the
 * effect's pre-roll before `at`, or 0 if there is none (the effect then
 * runs from the very first sample). So the pre-roll is 64-128 ms (Echo,
 * Reverb: 4.0-4.06 s), and S is always a chunk edge. Tom's fx_render.h says
 * why these numbers; his test_fx_resume.c checks the files they give. */
static uint32_t preroll_start(uint8_t effect, bool src_48k, uint32_t at)
{
    const bool long_memory = (effect == FXS_EFFECT_ECHO) || (effect == FXS_EFFECT_REVERB);
    const uint32_t preroll = long_memory ? FXJ_PREROLL_LONG_OUT : FXJ_PREROLL_SHORT_OUT;
    const uint32_t at_out = output_samples(at, src_48k);
    if (at_out <= preroll)
    {
        return 0U;
    }
    const uint32_t start_out = ((at_out - preroll) / FXJ_PREROLL_GRID_OUT) * FXJ_PREROLL_GRID_OUT;
    /* Back to source samples. At 32 kHz the grid is a whole number of
     * 64-sample blocks (3072 out = 32 x 96), so this is exact. */
    return src_48k ? start_out : (start_out / FXJ_OUT_PER_BLOCK) * FXP_BLOCK_SAMPLES;
}

/* THE ONE PLACE FOR A RESUME THAT IS NOT EXACT: the rebuild. FxRenderTask's
 * effect state is no longer this job's (why_not_exact says why), so carrying
 * on now would not sound like a file made in one go. Instead:
 *   1. the effect starts again at S, a little before the resume point R
 *      (preroll_start): the chunk at S carries FIRST;
 *   2. the output of [S, R) is thrown away: the .TMP has it already, and it
 *      only refills FxRenderTask's memory (delay lines, pitch detector);
 *   3. the chunk at R carries RESTORE and the job's carry at R (the park
 *      row kept it), so FxRenderTask puts back what never forgets;
 *   4. from R on the job writes to its kept .TMP as any job.
 * With S = 0 the effect runs from the first sample, so its state at R is the
 * one-go state already: no RESTORE. The job keeps the new number start_job
 * gave it. A rebuild never costs more than a restart: it renders R - S <= R
 * samples and writes nothing twice. */
static void resume_not_exact(fxj_t *j, uint32_t total)
{
    fxj_job_t *job = &j->job;
    const fxj_resume_t *r = &job->resume;
    const bool src_48k = source_is_48k(&job->src);
    const uint32_t from = preroll_start(job->effect, src_48k, r->src_at);
    fxp_rebuild(&job->pipe, total, from, r->src_at, r->out_at);
    const uint32_t preroll_ms = (output_samples(r->src_at, src_48k) - output_samples(from, src_48k)) /
                                FXJ_OUT_PER_MS;
    char line[FXJ_LOG_LEN];
    (void)snprintf(line, sizeof(line), "FX %s %s rebuilt, pre-roll %lu ms (%s)",
                   effect_name(job->effect), job->name, (unsigned long)preroll_ms, why_not_exact(j, r->id));
    log_line(j, line);
}

/* J_OPEN_SRC: where the pipe starts. Four cases, each set up by one call:
 *   a new job                                 from 0 (fxp_begin)
 *   resumed, but the recording changed        from 0, its .TMP unlinked
 *   resumed, FxRenderTask holds its state     exactly where it was parked
 *     (or nothing is left to render)
 *   resumed, any other case                   resume_not_exact(): rebuilt */
static fxj_fail_t plan_pipe(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    const fxj_resume_t *r = &job->resume;
    const uint32_t total = job->src.data_size / FXJ_BYTES_PER_SAMPLE;
    if (r->valid && !resume_matches(j, total))
    {
        const fxj_fail_t fail = start_again(j, "the recording changed");   /* r->valid is false now */
        if (fail != FXJ_FAIL_NONE)
        {
            return fail;
        }
    }
    if (!r->valid)
    {
        fxp_begin(&job->pipe, total);
        return FXJ_FAIL_NONE;
    }
    if (r->src_at >= total || dsp_still_holds(j, r->id))
    {
        carry_on_exactly(j, total);
        return FXJ_FAIL_NONE;
    }
    resume_not_exact(j, total);
    return FXJ_FAIL_NONE;
}

/* ======================================================================= */
/* The phases (one step each)                                               */
/* ======================================================================= */

static fxj_fail_t phase_mkdir_root(fxj_t *j)
{
    if (j->root_made)
    {
        return FXJ_FAIL_NONE;
    }
    const fxj_fail_t fail = fail_class(Storage_Mkdir(FXS_ROOT_DIR));
    if (fail == FXJ_FAIL_NONE)
    {
        j->root_made = true;
    }
    return fail;
}

static fxj_fail_t phase_mkdir_effect(fxj_t *j)
{
    const uint8_t bit = effect_bit(j->job.effect);
    if ((j->dirs_made & bit) != 0U)
    {
        return FXJ_FAIL_NONE;
    }
    char dir[FXS_PATH_LEN];
    if (!fx_dir_path(j->job.effect, dir, sizeof(dir)))
    {
        return FXJ_FAIL_REFUSED;
    }
    const fxj_fail_t fail = fail_class(Storage_Mkdir(dir));
    if (fail == FXJ_FAIL_NONE)
    {
        j->dirs_made |= bit;
    }
    return fail;
}

/* Why both names, in one step: f_rename is not atomic (FatFs writes the new
 * entry and removes the old one separately). A power loss in between leaves
 * NAME.TMP and NAME.WAV on ONE cluster chain. Creating the .TMP again would
 * free that chain and use it for new data, and a later unlink of the .WAV
 * would free it a second time: real corruption. Unlinking both names here,
 * before anything is allocated, frees the chain exactly once (the second
 * unlink stops at the cluster that is already free). Missing = fine.
 * A resumed job keeps its .TMP if it is as the park left it: a .TMP and a
 * .WAV on one chain need a power loss, which also empties the park table. */
static fxj_fail_t phase_clean(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    if (job->resume.valid)
    {
        const fxj_fail_t fail = check_kept_tmp(j);         /* a .TMP that changed is unlinked just below */
        if (fail != FXJ_FAIL_NONE)
        {
            return fail;
        }
    }
    storage_result_t r = STORAGE_OK;
    if (!job->resume.valid)
    {
        r = Storage_Unlink(job->tmp_path);
    }
    if (r != STORAGE_OK && r != STORAGE_NOT_FOUND)
    {
        return fail_class(r);
    }
    r = Storage_Unlink(job->wav_path);
    if (r != STORAGE_OK && r != STORAGE_NOT_FOUND)
    {
        return fail_class(r);
    }
    return FXJ_FAIL_NONE;
}

/* Read the recording's facts again (it may have changed since the check)
 * and keep it open at its first sample (a resumed job: at the sample where
 * it carries on). */
static fxj_fail_t phase_open_src(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    const storage_result_t r = open_source(j, job->name, &job->src);
    if (r == STORAGE_READ_FAIL)
    {
        return FXJ_FAIL_CARD_READ;
    }
    if (r == STORAGE_NO_SLOT)
    {
        return FXJ_FAIL_NO_SLOT;
    }
    if (r != STORAGE_OK)
    {
        return FXJ_FAIL_SOURCE;
    }
    job->src_open = true;
    if (!job->src.renderable)
    {
        return FXJ_FAIL_SOURCE;
    }
    const fxj_fail_t fail = plan_pipe(j);
    if (fail != FXJ_FAIL_NONE)
    {
        return fail;
    }
    if (Storage_Seek(job->src.data_offset + job->pipe.src_read * FXJ_BYTES_PER_SAMPLE) != STORAGE_OK)
    {
        return FXJ_FAIL_CARD_READ;
    }
    return FXJ_FAIL_NONE;
}

/* The new file plus a reserve must fit: 16 MB for a background job, so the
 * next recording never meets "Card full" because of effect files, and 1 MB
 * for the file the user waits for. The reserve follows the waited flag at
 * this moment. Free space is cached by FatFs: no card time. */
static fxj_fail_t phase_space(fxj_t *j)
{
    const fxj_job_t *job = &j->job;
    uint32_t free_kb = 0U;
    const fxj_fail_t fail = fail_class(Storage_FreeKb(&free_kb));
    if (fail != FXJ_FAIL_NONE)
    {
        return fail;
    }
    const uint32_t samples = output_samples(job->pipe.src_total, source_is_48k(&job->src)) -
                             job->pipe.out_written;     /* what is left: all of it, unless resumed */
    /* The new file's size in whole KB, plus 1 KB for its last part-KB (one
     * KB too many is harmless: this is only a free-space check). */
    const uint32_t file_kb = (FXS_HEADER_BYTES + samples * FXJ_BYTES_PER_SAMPLE) / FXJ_BYTES_PER_KB + 1U;
    const uint32_t reserve_kb = job->wanted ? FXJ_RESERVE_WAIT_KB : FXJ_RESERVE_BG_KB;
    return (free_kb < file_kb + reserve_kb) ? FXJ_FAIL_FULL : FXJ_FAIL_NONE;
}

/* The 68-byte header with the tag of this job's recording. */
static fxj_fail_t write_header(fxj_t *j, uint32_t data_bytes)
{
    const fxj_job_t *job = &j->job;
    fx_tag_t tag;
    fx_tag_from_src(&tag, FXJ_RENDER_VERSION, job->effect, &job->src);
    uint8_t header[FXS_HEADER_BYTES];
    (void)fx_build_header(&tag, data_bytes, header, sizeof(header));
    return fail_class(Storage_FxWrite(header, sizeof(header)));
}

/* The header says "data size 0" until J_CLOSE, so a file cut short by a
 * power loss never passes the check. The sync writes the directory entry
 * with the file's first cluster, so the next J_CLEAN can free its chain. */
static fxj_fail_t create_tmp(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    const storage_result_t r = Storage_FxCreate(job->tmp_path);
    if (r != STORAGE_OK)
    {
        return fail_class(r);
    }
    job->dst_open = true;
    const fxj_fail_t fail = write_header(j, 0U);
    if (fail != FXJ_FAIL_NONE)
    {
        return fail;
    }
    return fail_class(Storage_FxSync());
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): a resumed job whose .TMP
 * cannot be used after all starts from 0: a new .TMP, and the recording
 * read again from its first sample. */
static fxj_fail_t create_from_start(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    const fxj_fail_t fail = start_again(j, "its .TMP changed");
    if (fail != FXJ_FAIL_NONE)
    {
        return fail;
    }
    fxp_begin(&job->pipe, job->pipe.src_total);
    if (Storage_Seek(job->src.data_offset) != STORAGE_OK)
    {
        return FXJ_FAIL_CARD_READ;
    }
    return create_tmp(j);
}

/* A resumed job: its .TMP opened again, at its end, where the next sample
 * goes. J_CLEAN checked its size and nothing writes it in between, so a
 * .TMP that is gone or has another size here is a surprise: the file is
 * then made from the start, never refused. */
static fxj_fail_t reopen_tmp(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    const uint32_t end = tmp_bytes(job->pipe.out_written);
    uint32_t size = 0U;
    const storage_result_t r = Storage_FxOpenExisting(job->tmp_path, &size);
    if (r != STORAGE_OK && r != STORAGE_NOT_FOUND)
    {
        return fail_class(r);                    /* no lock slot: end_job_failed puts its row back */
    }
    if (r == STORAGE_OK)
    {
        job->dst_open = true;
        if (size == end)
        {
            char line[FXJ_LOG_LEN];
            (void)snprintf(line, sizeof(line), "FX %s %s resumed at %u%%",
                           effect_name(job->effect), job->name, (unsigned)job->resume.pct);
            log_line(j, line);
            job->resume.valid = false;           /* used up: from here on it runs as any job */
            return fail_class(Storage_FxSeek(end));
        }
        close_effect_file(j);
    }
    return create_from_start(j);
}

static fxj_fail_t phase_create(fxj_t *j)
{
    return j->job.resume.valid ? reopen_tmp(j) : create_tmp(j);
}

/* The real header (with the data size), then both files closed. A failed
 * close of the recording only asks for the remount: the effect file is
 * complete by then. */
static fxj_fail_t phase_close(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    fxj_fail_t fail = fail_class(Storage_FxSeek(0U));
    if (fail == FXJ_FAIL_NONE)
    {
        fail = write_header(j, job->pipe.out_written * FXJ_BYTES_PER_SAMPLE);
    }
    if (fail != FXJ_FAIL_NONE)
    {
        return fail;
    }
    job->dst_open = false;
    const storage_result_t r = Storage_FxClose();
    if (r != STORAGE_OK)
    {
        j->remount_wanted = true;
        fail = fail_class(r);
        return (fail != FXJ_FAIL_NONE) ? fail : FXJ_FAIL_CARD_WRITE;
    }
    job->src_open = false;
    close_read_file(j);
    return FXJ_FAIL_NONE;
}

/* From now on the file counts as made (J_CLEAN already removed the old .WAV). */
static fxj_fail_t phase_rename(fxj_t *j)
{
    return fail_class(Storage_Rename(j->job.tmp_path, j->job.wav_path));
}

/* One step of a phase other than J_RUN. */
static fxj_fail_t run_phase(fxj_t *j)
{
    switch (j->job.phase)
    {
        case J_MKDIR_ROOT:   return phase_mkdir_root(j);
        case J_MKDIR_EFFECT: return phase_mkdir_effect(j);
        case J_CLEAN:        return phase_clean(j);
        case J_OPEN_SRC:     return phase_open_src(j);
        case J_SPACE:        return phase_space(j);
        case J_CREATE:       return phase_create(j);
        case J_CLOSE:        return phase_close(j);
        case J_RENAME:       return phase_rename(j);
        default:             return FXJ_FAIL_REFUSED;
    }
}

/* The transition table at the top of this file, for a step that worked. */
static fxj_phase_t next_phase(fxj_phase_t phase)
{
    switch (phase)
    {
        case J_MKDIR_ROOT:   return J_MKDIR_EFFECT;
        case J_MKDIR_EFFECT: return J_CLEAN;
        case J_CLEAN:        return J_OPEN_SRC;
        case J_OPEN_SRC:     return J_SPACE;
        case J_SPACE:        return J_CREATE;
        case J_CREATE:       return J_RUN;
        case J_RUN:          return J_CLOSE;
        case J_CLOSE:        return J_RENAME;
        default:             return J_RENAME;
    }
}

/* ======================================================================= */
/* J_RUN: one pipe action per step                                          */
/* ======================================================================= */

/* READ: the next 8 KB of the recording into stage_in. Fewer bytes than
 * asked means the recording got shorter under the job. */
static fxj_fail_t run_read(fxj_t *j)
{
    fx_pipe_t *pipe = &j->job.pipe;
    const uint32_t samples = fxp_read_size(pipe);
    const size_t want_bytes = (size_t)samples * FXJ_BYTES_PER_SAMPLE;
    size_t got = 0U;
    if (Storage_ReadChunk((uint8_t *)j->stage_in, want_bytes, &got) != STORAGE_OK)
    {
        return FXJ_FAIL_CARD_READ;
    }
    if (got != want_bytes)
    {
        return FXJ_FAIL_SOURCE;
    }
    fxp_did_read(pipe, samples);
    return FXJ_FAIL_NONE;
}

/* SEND: hand the next chunk to FxRenderTask. False when it did not go: a
 * reply is still due (never two requests out), or the send was refused
 * (the chunk block not back in fxChunkPool, or the request queue full:
 * retried every FXJ_GUARD_WAIT_MS, a stall after FXJ_STALL_MS). */
static bool run_send(fxj_t *j, uint32_t now_ms)
{
    fxj_job_t *job = &j->job;
    if (j->req_out)
    {
        return false;
    }
    uint8_t flags = 0U;
    const uint32_t n = fxp_chunk(&job->pipe, &flags);
    const fxj_req_t req = {
        .job     = job->id,
        .n_in    = (uint16_t)n,
        .effect  = job->effect,
        .src_48k = source_is_48k(&job->src) ? 1U : 0U,
        .flags   = flags,
        .in      = &j->stage_in[job->pipe.stage_pos],
        .carry   = job->resume.carry,      /* read only with FXP_FLAG_RESTORE */
    };
    if (j->ops == NULL || j->ops->send == NULL || !j->ops->send(j->ops->ctx, &req))
    {
        if (!j->send_refused)
        {
            j->send_refused = true;
            j->refused_since_ms = now_ms;
        }
        return false;
    }
    j->send_refused = false;
    j->req_out = true;
    j->req_job = job->id;
    j->req_since_ms = now_ms;
    j->dsp_job = job->id;          /* FxRenderTask's effect state is this job's now */
    fxp_did_send(&job->pipe, n);
    /* ... and its TRUE one-go state only once a kept chunk is out: during a
     * rebuild's pre-roll it is not yet (the carry comes with the RESTORE
     * chunk at the resume point), so a park in the middle of a pre-roll is
     * never taken for exact. A fresh job keeps every chunk. */
    j->dsp_ok = fxp_reply_kept(&job->pipe);
    return true;
}

/* WRITE: all staged effect samples (at most 16 KB) to the .TMP. */
static fxj_fail_t run_write(fxj_t *j)
{
    fx_pipe_t *pipe = &j->job.pipe;
    const uint32_t samples = fxp_write_size(pipe);
    const fxj_fail_t fail = fail_class(Storage_FxWrite((const uint8_t *)j->stage_out,
                                                       (size_t)samples * FXJ_BYTES_PER_SAMPLE));
    if (fail != FXJ_FAIL_NONE)
    {
        return fail;
    }
    fxp_did_write(pipe, samples);
    return FXJ_FAIL_NONE;
}

static fxj_step_t step_run(fxj_t *j, uint32_t now_ms)
{
    fxj_job_t *job = &j->job;
    fxj_fail_t fail = FXJ_FAIL_NONE;
    switch (fxp_next(&job->pipe))
    {
        case FXP_READ:
            fail = run_read(j);
            break;
        case FXP_WRITE:
            fail = run_write(j);
            break;
        case FXP_SEND:
            if (!run_send(j, now_ms))
            {
                return FXJ_NOTHING;
            }
            break;
        case FXP_DONE:
            job->phase = J_CLOSE;
            break;
        default:
            return FXJ_NOTHING;                            /* FXP_WAIT: the reply is due */
    }
    if (fail != FXJ_FAIL_NONE)
    {
        return end_job_failed(j, fail);
    }
    j->progress++;
    return FXJ_BUSY;
}

/* ======================================================================= */
/* Parking (TEAM CODE, written by Brendon, 30 Oct 2026)                     */
/* ======================================================================= */

/* 0 before J_RUN (a resumed job: its percentage when parked), the pipe's
 * share during it, 100 after it. So the percentage never goes back across a
 * park and a resume, unless the job starts again from 0 (logged). */
static uint8_t job_percent(const fxj_t *j)
{
    const fxj_job_t *job = &j->job;
    if (!job->active)
    {
        return 0U;
    }
    if (job->phase < J_RUN)
    {
        return job->resume.valid ? job->resume.pct : 0U;
    }
    if (job->phase > J_RUN)
    {
        return FXJ_PERCENT_ALL;
    }
    return fxp_percent(&job->pipe);
}

/* The job's chunk is still out: the wait for its reply ran out (or nobody
 * waited). FxRenderTask has taken it, so its effect state is one chunk
 * further than the job's file: the resume will not be exact. The late reply
 * is dropped unread when it comes (fxj_on_reply: no running job has its
 * number then), so it never lands in stage_out, which a recording may be
 * using by then. */
static void give_up_chunk_out(fxj_t *j)
{
    if (fxj_job_chunk_out(j))
    {
        j->dsp_ok = false;
    }
}

/* Everything staged goes to the .TMP now: a recording overwrites stage_out
 * next, and staged input is simply read again when the job carries on. */
static fxj_fail_t write_staged(fxj_t *j)
{
    if (j->job.pipe.out_staged == 0U)
    {
        return FXJ_FAIL_NONE;
    }
    return run_write(j);                 /* all of it: at most FXP_STAGE_OUT_SAMPLES are ever staged */
}

/* The resume point of a job in J_RUN, J_CLOSE or J_RENAME whose staged
 * samples are written: the .TMP holds the output of fxp_kept_samples source
 * samples (src_done, or during a rebuild's pre-roll the point where it will
 * carry on). r->carry is already the carry at that point: take_reply keeps
 * it, and a pre-roll's replies never touch it. */
static void save_resume_point(fxj_t *j)
{
    fxj_job_t *job = &j->job;
    fxj_resume_t *r = &job->resume;
    r->pct    = job_percent(j);
    r->valid  = true;
    r->id     = job->id;
    r->src_at = fxp_kept_samples(&job->pipe);
    r->out_at = job->pipe.out_written;
    r->src    = job->src;
}

/* The park itself failed the job (a write error): a waited job's end waits
 * for the next fxj_step, so Jack's Preparing still hears of it. */
static void park_failed(fxj_t *j, fxj_fail_t fail)
{
    if (end_job_failed(j, fail) == FXJ_WANT_FAILED)
    {
        j->park_end = FXJ_WANT_FAILED;
    }
}

void fxj_park(fxj_t *j)
{
    if (j == NULL || !j->job.active)
    {
        return;
    }
    fxj_job_t *job = &j->job;
    if (job->fail_pending != FXJ_FAIL_NONE)
    {
        park_failed(j, job->fail_pending);               /* a reply had failed it already */
        return;
    }
    if (job->phase >= J_RUN)
    {
        give_up_chunk_out(j);
        const fxj_fail_t fail = write_staged(j);
        if (fail != FXJ_FAIL_NONE)
        {
            park_failed(j, fail);
            return;
        }
        if (fxp_kept_samples(&job->pipe) > 0U)           /* nothing rendered yet: nothing worth keeping */
        {
            save_resume_point(j);
        }
    }
    close_job_files(j);
    if (job->resume.valid)
    {
        put_row(j);
        char line[FXJ_LOG_LEN];
        (void)snprintf(line, sizeof(line), "FX %s %s parked at %u%%",
                       effect_name(job->effect), job->name, (unsigned)job->resume.pct);
        log_line(j, line);
    }
    forget_job(j);
    j->progress++;
}

/* The row of (name, effect) is set aside FIRST, then the slot job is parked:
 * the same order as fxj_want, so a full table drops nothing that the want
 * after it will need. */
void fxj_park_for(fxj_t *j, const char *name, uint8_t effect)
{
    if (j == NULL)
    {
        return;
    }
    if (name != NULL && effect != FXS_EFFECT_NONE)
    {
        hold_row(j, name, effect);
    }
    fxj_park(j);
}

bool fxj_job_chunk_out(const fxj_t *j)
{
    return (j != NULL) && j->req_out && j->job.active && (j->req_job == j->job.id);
}

/* ======================================================================= */
/* The step                                                                 */
/* ======================================================================= */

static fxj_step_t step_job(fxj_t *j, bool background_allowed, uint32_t now_ms)
{
    fxj_job_t *job = &j->job;
    if (job->wanted && fxj_stalled(j, now_ms))
    {
        return give_up(j);
    }
    if (!job->wanted && !background_allowed)
    {
        return FXJ_NOTHING;                                /* a background job waits */
    }
    if (job->fail_pending != FXJ_FAIL_NONE)
    {
        return end_job_failed(j, job->fail_pending);       /* a reply failed it */
    }
    if (job->phase == J_RUN)
    {
        return step_run(j, now_ms);
    }
    const fxj_fail_t fail = run_phase(j);
    if (fail != FXJ_FAIL_NONE)
    {
        return end_job_failed(j, fail);
    }
    if (job->phase == J_RENAME)
    {
        return end_job_done(j, now_ms);
    }
    job->phase = next_phase(job->phase);
    j->progress++;
    return FXJ_BUSY;
}

static bool background_can_run(const fxj_t *j, bool background_allowed, uint32_t now_ms)
{
    return background_allowed && !j->bg_halted && fxj_engine_ok(j, now_ms);
}

/* The source facts of a queued name: cached, or read now (one header read
 * per name until its next touch). False when the name cannot be used now:
 * missing or corrupt (all six pairs marked), a disk error (background
 * halted), or no free lock slot (a remount first; the pair stays once). */
static bool queued_source_facts(fxj_t *j, const char *name, uint8_t effect, fx_src_t *src)
{
    if (fxq_get_src(&j->queue, name, src))
    {
        return true;
    }
    const storage_result_t r = fxj_fingerprint(j, name, src);
    if (r == STORAGE_OK)
    {
        fxq_set_src(&j->queue, name, src);
        return true;
    }
    if (r == STORAGE_READ_FAIL)
    {
        halt_background(j, "card read failed");
        return false;
    }
    if (r == STORAGE_NO_SLOT)
    {
        if (!fxq_no_slot(&j->queue, name, effect))
        {
            fxq_mark(&j->queue, name, effect);
        }
        return false;
    }
    fxq_mark_all(&j->queue, name);
    return false;
}

/* One background CHECK: is FX/<effect>/<name>.WAV valid? If it is not,
 * start the job that makes it. */
static void check_pair(fxj_t *j, const char *name, uint8_t effect, uint32_t now_ms)
{
    fx_src_t src;
    if (!queued_source_facts(j, name, effect, &src))
    {
        return;
    }
    if (!src.renderable)
    {
        fxq_mark_all(&j->queue, name);                     /* too long, or not 32/48 kHz mono 16-bit */
        return;
    }
    const fxj_valid_t v = fxj_check(j, name, effect, &src, false, NULL);
    if (v == FXJ_VALID)
    {
        fxq_mark(&j->queue, name, effect);
        return;
    }
    if (v == FXJ_IO_ERROR)
    {
        halt_background(j, "card read failed");
        return;
    }
    fxj_resume_t resume;
    const bool resumes = take_row(j, name, effect, &resume);    /* a parked pair carries on */
    start_job(j, name, effect, false, now_ms, resumes ? &resume : NULL);
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): the parked pair that can
 * still carry on EXACTLY, or NULL. Only one can: FxRenderTask holds the
 * state of one job at most (dsp_job), and only if it is that job's true
 * one-go state (dsp_ok). It must still have something to render, and the
 * queue must still list the pair (a pair it dropped waits for the next
 * touch). */
static const fxj_parked_t *exact_row(const fxj_t *j)
{
    for (uint32_t i = 0U; i < FXJ_PARK_ROWS; i++)
    {
        const fxj_parked_t *row = &j->parked[i];
        const uint32_t total = row->resume.src.data_size / FXJ_BYTES_PER_SAMPLE;
        if (row->used && dsp_still_holds(j, row->resume.id) && row->resume.src_at < total &&
            fxq_is_queued(&j->queue, row->name, row->effect))
        {
            return row;
        }
    }
    return NULL;
}

/* The next background pair: the queue's order (fx_queue.c), with one
 * exception. A parked job that can still carry on exactly goes first: any
 * other job's first chunk would replace its effect state in FxRenderTask,
 * and then it would need a rebuild (a pre-roll of 64 ms, or 4 s for Echo
 * and Reverb). For example, Autotune is made in the background, PLAY of the
 * original parks it, and after STOP it carries on before the cheaper
 * effects the PLAY queued. */
static bool next_background_pair(const fxj_t *j, char name[FXS_NAME_LEN], uint8_t *effect)
{
    const fxj_parked_t *row = exact_row(j);
    if (row == NULL)
    {
        return fxq_next(&j->queue, name, effect);
    }
    memcpy(name, row->name, FXS_NAME_LEN);                 /* a copy: check_pair empties the row */
    *effect = row->effect;
    return true;
}

static fxj_step_t step_background(fxj_t *j, bool background_allowed, uint32_t now_ms)
{
    char name[FXS_NAME_LEN];
    uint8_t effect = FXS_EFFECT_NONE;
    if (!next_background_pair(j, name, &effect))
    {
        j->busy_latch = false;                             /* the batch is over: fx_busy falls */
        return FXJ_NOTHING;
    }
    if (!background_can_run(j, background_allowed, now_ms))
    {
        return FXJ_NOTHING;
    }
    check_pair(j, name, effect, now_ms);
    j->progress++;
    return FXJ_BUSY;
}

fxj_step_t fxj_step(fxj_t *j, bool background_allowed, uint32_t now_ms)
{
    if (j == NULL)
    {
        return FXJ_NOTHING;
    }
    put_back_held(j);                                  /* no fxj_want came for the held row */
    if (j->park_end != FXJ_NOTHING)
    {
        const fxj_step_t end = j->park_end;            /* a park failed the waited job: say so first */
        j->park_end = FXJ_NOTHING;
        j->progress++;
        return end;
    }
    if (j->job.active)
    {
        return step_job(j, background_allowed, now_ms);
    }
    return step_background(j, background_allowed, now_ms);
}

bool fxj_can_act(const fxj_t *j, bool background_allowed, uint32_t now_ms)
{
    if (j == NULL)
    {
        return false;
    }
    const fxj_job_t *job = &j->job;
    if (j->park_end != FXJ_NOTHING)
    {
        return true;                                       /* the step that reports a park's failure */
    }
    if (!job->active)
    {
        return background_can_run(j, background_allowed, now_ms) && fxq_next(&j->queue, NULL, NULL);
    }
    if (job->wanted && fxj_stalled(j, now_ms))
    {
        return true;                                       /* the step that gives up */
    }
    if (!job->wanted && !background_allowed)
    {
        return false;
    }
    if (job->fail_pending != FXJ_FAIL_NONE || job->phase != J_RUN)
    {
        return true;                                       /* a phase step always moves */
    }
    switch (fxp_next(&job->pipe))
    {
        case FXP_SEND: return !j->req_out;                 /* never SEND while a request is out */
        case FXP_WAIT: return false;
        default:       return true;                        /* READ, WRITE, DONE */
    }
}

/* ======================================================================= */
/* Replies                                                                  */
/* ======================================================================= */

/* TEAM CODE (written by Brendon, 30 Oct 2026): the carry after a kept
 * chunk is the job's carry at its new src_done; a later rebuild sends it
 * back. A reply without one leaves zeros, which FxRenderTask refuses
 * (BAD_REQUEST: the job stops) rather than make a wrong file. */
static void keep_carry(fxj_job_t *job, const fxj_reply_t *reply)
{
    if (reply->carry != NULL)
    {
        memcpy(job->resume.carry, reply->carry, FXJ_CARRY_BYTES);
    }
    else
    {
        memset(job->resume.carry, 0, FXJ_CARRY_BYTES);
    }
}

/* The current job's reply: its status, then its samples into stage_out. */
static void take_reply(fxj_t *j, const fxj_reply_t *reply)
{
    fxj_job_t *job = &j->job;
    if (reply->status == FXJ_STATUS_NO_ENGINE)
    {
        j->engine_absent = true;                           /* no background job starts any more */
        j->dsp_ok = false;                                 /* FxRenderTask did not run the chunk */
        job->fail_pending = FXJ_FAIL_NO_ENGINE;
        return;
    }
    if (reply->status == FXJ_STATUS_BAD_REQUEST)
    {
        j->dsp_ok = false;                                 /* FxRenderTask did not run the chunk */
        job->fail_pending = FXJ_FAIL_BAD_REQUEST;
        return;
    }
    if (reply->status != FXJ_STATUS_OK && !job->dry_logged)
    {
        char line[FXJ_LOG_LEN];
        (void)snprintf(line, sizeof(line), "FX %s %s: part of a chunk went through dry (status %u)",
                       effect_name(job->effect), job->name, (unsigned)reply->status);
        log_line(j, line);
        job->dry_logged = true;                            /* once per job; the job goes on */
    }
    if (!fxp_reply_kept(&job->pipe))
    {
        fxp_did_reply(&job->pipe, 0U);                     /* a rebuild's pre-roll: it only refilled
                                                            * FxRenderTask's memory, nothing is kept */
        return;
    }
    /* The reply's length is not trusted: at most one chunk's output, and
     * never more than stage_out has room for (more would write past its
     * end). */
    const uint32_t room = FXP_STAGE_OUT_SAMPLES - job->pipe.out_staged;
    const uint32_t n = min_u32(min_u32(reply->n_out, FXP_CHUNK_OUT), room);
    if (n > 0U && reply->out != NULL)
    {
        memcpy(&j->stage_out[job->pipe.out_staged], reply->out, (size_t)n * sizeof(int16_t));
    }
    keep_carry(job, reply);
    fxp_did_reply(&job->pipe, n);
}

void fxj_on_reply(fxj_t *j, const fxj_reply_t *reply)
{
    if (j == NULL || reply == NULL)
    {
        return;
    }
    /* One request is out at most, so any reply means none is out now. */
    j->req_out = false;
    j->progress++;
    const fxj_job_t *job = &j->job;
    const bool for_this_job = job->active && job->phase == J_RUN && job->pipe.inflight &&
                              reply->job == job->id;
    if (!for_this_job)
    {
        return;                                            /* a late reply of an aborted job, or of a chunk
                                                            * a park gave up: dropped unread */
    }
    take_reply(j, reply);
}

/* ======================================================================= */
/* The rest of the interface                                                */
/* ======================================================================= */

void fxj_init(fxj_t *j, const fxj_ops_t *ops, int16_t *stage_in, int16_t *stage_out, uint8_t *scratch)
{
    if (j == NULL)
    {
        return;
    }
    memset(j, 0, sizeof(*j));
    j->ops = ops;
    j->stage_in = stage_in;
    j->stage_out = stage_out;
    j->scratch = scratch;
    fxq_init(&j->queue);
    j->next_id = FXJ_FIRST_JOB_ID;
}

/* What a card change clears: the queue and the park table with its held
 * row (their names belong to the old card), the folder bits, the halt flag
 * and the remount request. The job counter and the request-out record stay
 * (only fxj_init sets them). */
static void forget_card(fxj_t *j)
{
    fxq_clear(&j->queue);
    memset(j->parked, 0, sizeof(j->parked));
    memset(&j->held, 0, sizeof(j->held));
    j->root_made = false;
    j->dirs_made = 0U;
    j->bg_halted = false;
    j->remount_wanted = false;
    j->busy_latch = false;
}

void fxj_on_mount(fxj_t *j, const char *last_name)
{
    if (j == NULL)
    {
        return;
    }
    fxj_abort(j);                 /* a job left from before the mount would hold the old volume's files */
    forget_card(j);
    if (last_name != NULL && last_name[0] != '\0')
    {
        fxq_touch(&j->queue, last_name);
    }
}

void fxj_on_unmount(fxj_t *j)
{
    if (j == NULL)
    {
        return;
    }
    fxj_abort(j);
    forget_card(j);
}

void fxj_select(fxj_t *j, uint8_t effect)
{
    if (j != NULL)
    {
        fxq_select(&j->queue, effect);
    }
}

void fxj_touch(fxj_t *j, const char *name)
{
    if (j == NULL)
    {
        return;
    }
    /* Nothing was left to do: whatever comes now is a new batch, which sets
     * fx_busy only if a job starts (checks alone never do). */
    if (!j->job.active && !fxq_next(&j->queue, NULL, NULL))
    {
        j->busy_latch = false;
    }
    fxq_touch(&j->queue, name);
}

void fxj_forget(fxj_t *j, const char *name)
{
    if (j == NULL || name == NULL)
    {
        return;
    }
    if (j->job.active && strncmp(j->job.name, name, FXS_NAME_LEN) == 0)
    {
        fxj_abort(j);             /* for good: nothing more is written into files about to go */
    }
    drop_rows_of(j, name);
    fxq_forget(&j->queue, name);
}

bool fxj_is_running(const fxj_t *j, const char *name, uint8_t effect)
{
    if (j == NULL || name == NULL || !j->job.active)
    {
        return false;
    }
    return (j->job.effect == effect) && (strncmp(j->job.name, name, FXS_NAME_LEN) == 0);
}

fxj_want_t fxj_want(fxj_t *j, const char *name, uint8_t effect, uint32_t now_ms)
{
    if (fxj_is_running(j, name, effect))
    {
        j->job.wanted = true;                              /* keeps its progress: nothing restarts */
        return FXJ_ADOPTED;
    }
    /* A swap. The wanted pair's row comes out FIRST (from j->held if Jack's
     * glue set it aside with fxj_park_for, else from the table), so the park
     * of the slot job just below can never drop it to make room: going
     * A -> B -> A keeps the rows of both. */
    fxj_resume_t resume;
    const bool resumes = take_row(j, name, effect, &resume);
    fxj_park(j);
    put_back_held(j);                                      /* a row held for another pair goes back */
    start_job(j, name, effect, true, now_ms, resumes ? &resume : NULL);
    return FXJ_STARTED;
}

void fxj_unwant(fxj_t *j)
{
    if (j != NULL)
    {
        j->job.wanted = false;
    }
}

void fxj_abort(fxj_t *j)
{
    if (j == NULL || !j->job.active)
    {
        return;
    }
    close_job_files(j);
    forget_job(j);
}

bool fxj_request_out(const fxj_t *j)
{
    return (j != NULL) && j->req_out;
}

uint32_t fxj_progress(const fxj_t *j)
{
    return (j != NULL) ? j->progress : 0U;
}

uint32_t fxj_idle_wait_ms(bool can_act, bool last_pass_idle)
{
    if (!can_act)
    {
        return FXJ_IDLE_WAIT_MS;
    }
    return last_pass_idle ? FXJ_GUARD_WAIT_MS : 0U;
}

bool fxj_stalled(const fxj_t *j, uint32_t now_ms)
{
    if (j == NULL)
    {
        return false;
    }
    if (j->req_out && (now_ms - j->req_since_ms) > FXJ_STALL_MS)
    {
        return true;
    }
    return j->send_refused && (now_ms - j->refused_since_ms) > FXJ_STALL_MS;
}

bool fxj_engine_ok(const fxj_t *j, uint32_t now_ms)
{
    return (j != NULL) && !j->engine_absent && !fxj_stalled(j, now_ms);
}

bool fxj_take_remount(fxj_t *j)
{
    if (j == NULL || !j->remount_wanted)
    {
        return false;
    }
    j->remount_wanted = false;
    return true;
}

fxj_fail_t fxj_last_fail(const fxj_t *j)
{
    return (j != NULL) ? j->last_fail : FXJ_FAIL_NONE;
}

void fxj_want_src(const fxj_t *j, fx_src_t *src)
{
    if (j != NULL && src != NULL)
    {
        *src = j->job.src;
    }
}

uint8_t fxj_want_percent(const fxj_t *j)
{
    if (j == NULL || !j->job.active || !j->job.wanted)
    {
        return 0U;
    }
    return round_down(job_percent(j), FXJ_PCT_STEP_WAIT);
}

void fxj_status(const fxj_t *j, bool background_allowed, uint32_t now_ms, fxj_status_t *out)
{
    if (out == NULL)
    {
        return;
    }
    memset(out, 0, sizeof(*out));
    if (j == NULL)
    {
        return;
    }
    /* fx_busy: from the start of a job until the queue has nothing left,
     * while that work can run. It stays on between the jobs of a batch, so
     * the SD BUSY chip does not blink. */
    const bool work_left = j->job.active || fxq_next(&j->queue, NULL, NULL);
    out->busy = j->busy_latch && work_left && background_can_run(j, background_allowed, now_ms);
    if (!j->job.active)
    {
        return;
    }
    out->job_effect = j->job.effect;
    out->job_pct = round_down(job_percent(j), FXJ_PCT_STEP_BG);
    memcpy(out->job_name, j->job.name, FXS_NAME_LEN);
}

void fxj_clear_halt(fxj_t *j)
{
    if (j != NULL)
    {
        j->bg_halted = false;
    }
}

uint32_t fxj_files_made(const fxj_t *j)
{
    return (j != NULL) ? j->files_made : 0U;
}
